import{_ as a}from"./chunks/protocol.BCHVaPua.js";import{_ as e,o as r,c as o,a2 as i}from"./chunks/framework.BefGvJmu.js";const _=JSON.parse('{"title":"PAI 协议","description":"个人 AI 应用怎样通过 PAI 服务发布、更新和读取内容。","frontmatter":{"title":"PAI 协议","description":"个人 AI 应用怎样通过 PAI 服务发布、更新和读取内容。"},"headers":[],"relativePath":"zh/protocol.md","filePath":"zh/protocol.md"}'),d={name:"zh/protocol.md"};function l(p,t,s,h,n,c){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="pai-协议" tabindex="-1">PAI 协议 <a class="header-anchor" href="#pai-协议" aria-label="Permalink to &quot;PAI 协议&quot;">​</a></h1><p>PAI 约定个人 AI 应用怎样通过服务发布、更新和读取内容。当前内容协议让客户端用共同的方式发现接口、上传文档、取得素材，并保留来源链接。</p><h2 id="谁负责哪一部分" tabindex="-1">谁负责哪一部分 <a class="header-anchor" href="#谁负责哪一部分" aria-label="Permalink to &quot;谁负责哪一部分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参与者</th><th>职责</th></tr></thead><tbody><tr><td>宿主应用</td><td>人和自己的 AI 使用的工具或 Harness，通过 PAI 客户端接入服务。</td></tr><tr><td>PAI 客户端</td><td>发现服务接口，执行发布或读取操作。</td></tr><tr><td>PAI 服务端</td><td>在服务中实现内容接口，验证文件、检查发布权限、提供历史版本。</td></tr><tr><td>服务提供者</td><td>运行服务端，提供账号、存储和产品界面。</td></tr></tbody></table><p>所选服务同时接收发布和读取请求。平台可以把这些接口接入现有系统。Follo 是潜在的服务提供者之一。</p><p><img src="'+a+'" alt="发布者和读者通过客户端使用同一个 PAI 服务。"></p><h2 id="发布、更新、读取" tabindex="-1">发布、更新、读取 <a class="header-anchor" href="#发布、更新、读取" aria-label="Permalink to &quot;发布、更新、读取&quot;">​</a></h2><p>客户端从 <code>/.well-known/pai.json</code> 开始，取得服务支持的能力、接受的文件格式和接口地址。</p><p><strong>发布。</strong> 客户端带上发布凭据，上传完整的 <code>.pai</code> 或 <code>.pai.html</code> 文件。服务端验证文件，保存一个发布版本，并返回资源及其不同读取形式的地址。</p><p><strong>更新。</strong> 发布者把修改后的文档提交到该资源的更新地址。新的文档修订产生新的发布版本。同一修订和内容再次提交时，返回已经保存的版本。</p><p><strong>读取。</strong> 读者从目录中选择资源，或直接使用已知资源地址。结构化内容提供按阅读顺序排列的 Markdown 内容块、图片信息和来源链接。需要原图时，再取得完整文件中的图片字节。</p><p><a href="/pai-website/spec/service.html">阅读内容服务规范（英文）</a> · <a href="/pai-website/guide/architecture.html">查看完整架构（英文）</a></p><h2 id="来源跟随具体版本" tabindex="-1">来源跟随具体版本 <a class="header-anchor" href="#来源跟随具体版本" aria-label="Permalink to &quot;来源跟随具体版本&quot;">​</a></h2><p>文档 ID 随文件保存，文档修订号记录内容编辑。服务为已发布文档分配资源 ID 和发布版本号。</p><p>每个返回的内容块都有 <code>sourceUrl</code>，指向某个发布版本中的具体位置。后续更新仍保留这个旧版本。客户端复用素材时，可以同时保存文档、发布版本、内容块和图片的标识。</p><p>发布和更新使用 Bearer 凭据。当前协议中的已发布内容可公开读取。服务根据凭据确定发布权限。</p><h2 id="接入当前草案" tabindex="-1">接入当前草案 <a class="header-anchor" href="#接入当前草案" aria-label="Permalink to &quot;接入当前草案&quot;">​</a></h2><p>参考实现提供发布客户端、读取客户端、HTTP 服务端，以及通过声明接口检查服务的命令。</p><ul><li><a href="/pai-website/guide/client.html">客户端接入（英文）</a>：让 AI 应用或 Harness 使用 PAI 服务。</li><li><a href="/pai-website/guide/server.html">服务端接入（英文）</a>：在平台中实现当前内容协议。</li><li><a href="/pai-website/spec/">规范总览（英文）</a>：查看规范要求、数据结构和固定样例。</li></ul><p>当前协议版本为 <code>0.1.0-draft.1</code>。正式规范以英文维护，本页用于说明项目及接入思路。</p><h2 id="后续扩展" tabindex="-1">后续扩展 <a class="header-anchor" href="#后续扩展" aria-label="Permalink to &quot;后续扩展&quot;">​</a></h2><p>查询检索将利用已有的发布版本、内容块标识和来源链接，按请求返回相关素材。托管代理部分将约定服务如何在用户授权范围内运行对外代理。这两项属于后续规划，通信格式待制定。</p>',22)])])}const P=e(d,[["render",l]]);export{_ as __pageData,P as default};
